css:
:scope{display:block;width:100%}.pw{--bg:#01111D;--tx:#EDE6D8;--lb:#BBAFA3;--hl:#7B868066;--ol:#BBAFA3;background:var(--bg);color:var(--tx);font-family:var(--os-font-body);font-weight:400}.pw[data-ground="bone"]{--bg:#E0D9CB;--tx:#01111D;--lb:#5E3A3C;--hl:#BBAFA3;--ol:#01111D}.pw[data-ground="sand"]{--bg:#BBAFA3;--tx:#01111D;--lb:#5E3A3C;--hl:#01111D40;--ol:#01111D}.pw[data-ground="olive"]{--bg:#182727}.pw[data-ground="oxblood"]{--bg:#321013;--hl:#95665A}.pw[data-ground="umber"]{--bg:#5E3A3C;--hl:#BBAFA366}.pw[data-ground="clay"]{--bg:#8C5B46;--lb:#EDE6D8;--hl:#EDE6D899;--ol:#EDE6D8}.pw[data-ground="sage"]{--bg:#7B8680;--tx:#01111D;--lb:#01111D;--hl:#01111D40;--ol:#01111D}
.pw__in{box-sizing:content-box;max-width:1200px;margin:0 auto;padding:104px 32px;display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:48px}
.pw__blk{border-top:1px solid var(--hl);padding-top:28px}
.pw__kicker{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.32em;text-transform:uppercase;color:var(--lb)}
.pw__hl{margin:16px 0 0;font-family:var(--os-font-heading);font-weight:500;font-size:32px;line-height:1.2}
.pw__bd{margin:12px 0 0;font-size:19px;line-height:1.5;color:var(--lb)}
.pw__btns{display:flex;flex-wrap:wrap;gap:14px;margin-top:24px}
.pw__btn{display:inline-block;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.22em;text-transform:uppercase;text-decoration:none;line-height:normal;color:var(--tx);border:1px solid var(--ol);padding:15px 22px}
.pw__btn:focus-visible{outline:2px solid var(--tx);outline-offset:3px}
@media (max-width:767px){.pw__in{padding:64px 20px;grid-template-columns:1fr;gap:40px}.pw__kicker{font-size:12px;letter-spacing:.24em}.pw__hl{font-size:27px}.pw__btns{flex-direction:column}.pw__btn{text-align:center}}
